#!/usr/bin/env python3
"""Generate biology_unit2/3/4_content.py from NCERT Class 10 Ch 6–8 card data."""

from __future__ import annotations

from pathlib import Path

SCRIPT_DIR = Path(__file__).resolve().parent

HEADER = '''"""Full concept card content for Harshit Biology Unit {unit} — Days 1–16 ({chapter})."""

from __future__ import annotations


def _card(
    cid: str,
    name: str,
    simple: str,
    visual_type: str,
    visual_config: dict | None,
    why: str,
    example: str,
    remember: str,
    confusion: str = "",
    optional: str = "",
    glossary: list[str] | None = None,
) -> dict:
    return {{
        "id": cid,
        "name": name,
        "simple_answer": simple,
        "visual": {{"type": visual_type, **(visual_config or {{}})}},
        "why": why,
        "example": example,
        "remember": remember,
        "common_confusion": confusion,
        "optional_detail": optional,
        "glossary_terms": glossary or [],
    }}


def _build_day(day: int, cards: list[tuple]) -> list[dict]:
    out = []
    for i, row in enumerate(cards, 1):
        name, simple, vtype, vcfg, why, ex, rem, *rest = row
        confusion = rest[0] if len(rest) > 0 else ""
        optional = rest[1] if len(rest) > 1 else ""
        gloss = rest[2] if len(rest) > 2 else []
        out.append(
            _card(
                f"u{unit}_d{{day}}_c{{i:02d}}",
                name,
                simple,
                vtype,
                vcfg if isinstance(vcfg, dict) else {{}},
                why,
                ex,
                rem,
                confusion,
                optional,
                gloss if isinstance(gloss, list) else [],
            )
        )
    return out

'''

FOOTER = '''
DAY_BUILDERS = {{
{builders}
}}

DAY_TITLES = {{
{titles}
}}
'''


def _fmt_row(row: tuple) -> str:
    return "    " + repr(row)


def render_unit(unit: int, chapter: str, days: list[tuple[str, list[tuple]]]) -> str:
    lines = [HEADER.format(unit=unit, chapter=chapter)]
    for day_num, (_title, cards) in enumerate(days, 1):
        lines.append(f"DAY{day_num} = _build_day({day_num}, [")
        for card in cards:
            lines.append(f"    {repr(card)},")
        lines.append("])")
        lines.append("")
    builders = ",\n".join(f"    {d}: lambda: DAY{d}" for d in range(1, 17))
    titles = ",\n".join(f'    {d}: "{days[d - 1][0]}"' for d in range(1, 17))
    lines.append(FOOTER.format(builders=builders, titles=titles))
    return "\n".join(lines)


