UNITS = [
    (2, "Ch 6 Control and Coordination", UNIT2_DAYS, "biology_unit2_content.py"),
    (3, "Ch 7 How do Organisms Reproduce?", UNIT3_DAYS, "biology_unit3_content.py"),
    (4, "Ch 8 Heredity", UNIT4_DAYS, "biology_unit4_content.py"),
]


def count_cards(days: list[tuple[str, list[tuple]]]) -> int:
    return sum(len(cards) for _, cards in days)


def verify_unit(unit: int, days: list[tuple[str, list[tuple]]]) -> None:
    if len(days) != 16:
        raise ValueError(f"Unit {unit}: expected 16 days, got {len(days)}")
    for day_num, (title, cards) in enumerate(days, 1):
        if len(cards) != 10:
            raise ValueError(f"Unit {unit} day {day_num} ({title}): expected 10 cards, got {len(cards)}")
    total = count_cards(days)
    if total != 160:
        raise ValueError(f"Unit {unit}: expected 160 cards, got {total}")


def main() -> None:
    results: list[str] = []
    for unit, chapter, days, filename in UNITS:
        verify_unit(unit, days)
        out_path = SCRIPT_DIR / filename
        content = render_unit(unit, chapter, days)
        out_path.write_text(content, encoding="utf-8")
        total = count_cards(days)
        results.append(f"  {filename}: {total} cards ({len(days)} days x 10)")
        assert "DAY_BUILDERS" in content
        assert "DAY_TITLES" in content
    print("Generated biology unit content files:")
    print("\n".join(results))


if __name__ == "__main__":
    main()
